// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.24;

/**
 * @title TickMath
 * @notice Computes sqrt price for ticks of size 1.0001, i.e. sqrt(1.0001^tick) as fixed point Q64.96 numbers.
 * @dev Adapted from Uniswap V3 (https://github.com/Uniswap/v3-core).
 *      Supports prices between 2**-128 and 2**128.
 */
library TickMath {
    /// @dev The minimum tick that may be passed to #getSqrtRatioAtTick computed from log base 1.0001 of 2**-128.
    int24 internal constant MIN_TICK = -887272;
    /// @dev The maximum tick that may be passed to #getSqrtRatioAtTick computed from log base 1.0001 of 2**128.
    int24 internal constant MAX_TICK = -MIN_TICK;

    /// @dev The minimum value that can be returned from #getSqrtRatioAtTick. Equivalent to getSqrtRatioAtTick(MIN_TICK).
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    /// @dev The maximum value that can be returned from #getSqrtRatioAtTick. Equivalent to getSqrtRatioAtTick(MAX_TICK).
    uint160 internal constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;

    /// @notice Calculates sqrt(1.0001^tick) * 2^96.
    /// @dev Throws if |tick| > max tick.
    /// @param tick The input tick for the above formula.
    /// @return sqrtPriceX96 A Fixed point Q64.96 number representing the sqrt of the ratio of the two assets (token1/token0)
    ///         at the given tick.
    function getSqrtRatioAtTick(int24 tick) internal pure returns (uint160 sqrtPriceX96) {
        uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
        require(absTick <= uint256(int256(MAX_TICK)), "T");

        // Uniswap V3 math requires unchecked arithmetic — intermediate products
        // intentionally overflow uint256 but the final >> 128 brings them back in range.
        unchecked {
            uint256 ratio = absTick & 0x1 != 0 ? 0xfffcb933bd6fad37aa2d162d1a594001 : 0x100000000000000000000000000000000;
            if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
            if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
            if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
            if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
            if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
            if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
            if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
            if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
            if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
            if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
            if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
            if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
            if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
            if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
            if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
            if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;

            if (tick > 0) ratio = type(uint256).max / ratio;

            // this divides by 1<<32 rounding up to go from a Q128.128 to a Q128.96.
            // we then downcast because we know the result always fits within 160 bits due to our tick input constraint
            // we round up in the division so getTickAtSqrtRatio of the output price is always consistent
            sqrtPriceX96 = uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }
}

src/interfaces/IsDIEMv2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {IERC1271} from "@openzeppelin/contracts/interfaces/IERC1271.sol";

/**
 * @title IsDIEMv2
 * @notice Interface for Staked DIEM v2 — ERC-20 + EIP-2612 + Synthetix-style rewards.
 *
 * sDIEM v2 is a transferable ERC-20 representing a claim on staked DIEM.
 * Stakers deposit DIEM, earn USDC rewards, and can transfer their sDIEM
 * freely to anyone (including ERC-4626 wrappers, lending markets, etc).
 *
 * DIEM is forward-staked on Venice for compute credits, exactly as in v1.
 * Withdrawals use a request/complete pattern with a 24h delay matching
 * Venice's cooldown.
 *
 * Differences from v1:
 *   - Full ERC-20 surface (transfer/transferFrom/approve + EIP-2612 permit).
 *   - Reward accounting checkpointed on every transfer via _update hook —
 *     prevents the Synthetix-ERC20 reward-leak trap.
 *   - Withdrawal queue is per-address and does NOT transfer with sDIEM.
 *     If Alice has 10 sDIEM + 5 queued, transferring sDIEM to Bob moves
 *     only liquid sDIEM. Alice keeps her queued withdrawal.
 */
interface IsDIEMv2 is IERC20, IERC20Permit, IERC1271 {
    // ── Structs ─────────────────────────────────────────────────────────────

    struct WithdrawalRequest {
        uint256 amount;
        uint256 requestedAt;
    }

    // ── Events ──────────────────────────────────────────────────────────────

    event Staked(address indexed user, uint256 amount);
    event WithdrawalRequested(address indexed user, uint256 amount);
    event WithdrawalCompleted(address indexed user, uint256 amount);
    event WithdrawalCancelled(address indexed user, uint256 amount);
    event RewardPaid(address indexed user, uint256 reward);
    event RewardNotified(uint256 reward, uint256 rewardRate, uint256 periodFinish);
    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event OperatorChanged(address indexed oldOperator, address indexed newOperator);
    event AdminTransferStarted(address indexed currentAdmin, address indexed pendingAdmin);
    event AdminTransferred(address indexed oldAdmin, address indexed newAdmin);
    event TokenRecovered(address indexed token, address indexed to, uint256 amount);

    event VeniceClaimed(address indexed caller, uint256 amount);
    event ExcessRedeployed(address indexed caller, uint256 amount);
    event VeniceUnstakeInitiated(address indexed caller, uint256 amount);

    // ── Views ───────────────────────────────────────────────────────────────

    function diem() external view returns (IERC20);
    function usdc() external view returns (IERC20);
    function admin() external view returns (address);
    function pendingAdmin() external view returns (address);
    function operator() external view returns (address);
    function paused() external view returns (bool);

    /// @notice Total sDIEM in existence; equals total DIEM currently staked
    ///         (not counting amounts pending withdrawal, which are burned).
    function totalStaked() external view returns (uint256);

    function earned(address account) external view returns (uint256);

    function rewardRate() external view returns (uint256);
    function rewardPerToken() external view returns (uint256);
    function periodFinish() external view returns (uint256);
    function lastUpdateTime() external view returns (uint256);

    function totalPendingWithdrawals() external view returns (uint256);
    function totalPendingNotInitiated() external view returns (uint256);

    function withdrawalRequests(address account) external view returns (uint256 amount, uint256 requestedAt);
    function canCompleteWithdraw(address account) external view returns (bool);
    function veniceCooldownEnd() external view returns (uint256);

    function WITHDRAWAL_DELAY() external view returns (uint256);

    // ── Mutative — staking ──────────────────────────────────────────────────

    function stake(uint256 amount) external;
    function requestWithdraw(uint256 amount) external;
    function completeWithdraw() external;
    function cancelWithdraw() external;
    function claimReward() external;
    function claimRewardTo(address to) external;
    function exit() external;

    // ── Permissionless — Venice management ──────────────────────────────────

    function claimFromVenice() external;
    function redeployExcess() external;
    function initiateVeniceUnstake() external;

    // ── Operator ────────────────────────────────────────────────────────────

    function notifyRewardAmount(uint256 reward) external;

    // ── Admin ───────────────────────────────────────────────────────────────

    function pause() external;
    function unpause() external;
    function setOperator(address newOperator) external;
    function transferAdmin(address newAdmin) external;
    function acceptAdmin() external;
    function recoverERC20(address token, address to, uint256 amount) external;
}

src/interfaces/IcsDIEMv2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IsDIEMv2} from "./IsDIEMv2.sol";

/**
 * @title IcsDIEMv2
 * @notice Compounding Staked DIEM v2 — canonical ERC-4626 wrapper over sDIEM v2.
 *
 * `asset() == sDIEM v2`. Mental model: wstETH over stETH.
 *
 *   deposit(sDIEMv2) → mint csDIEMv2 shares
 *   redeem(csDIEMv2) → burn shares, return sDIEMv2 (synchronous, standard 4626)
 *
 * harvest() claims USDC rewards from sDIEM v2, swaps USDC → DIEM via Slipstream
 * (TWAP-protected, Pashov-audited), then sdiem.stake(diem). Vault's sDIEM
 * balance grows → totalAssets() grows → share price ticks up monotonically.
 *
 * Includes a depositDIEM(uint256, address) zap for users holding raw DIEM —
 * the vault stakes into sDIEM internally and mints shares against the result.
 *
 * Composable with Pendle, Morpho/MetaMorpho, Spectra, Silo, and anything
 * expecting standard ERC-4626 semantics.
 */
interface IcsDIEMv2 is IERC4626 {
    // ── Events ──────────────────────────────────────────────────────────────

    /// @notice Emitted when harvest converts USDC rewards into compounded DIEM.
    event Harvested(address indexed caller, uint256 usdcAmount, uint256 diemStaked);

    /// @notice Emitted when a user zap-deposits raw DIEM (vault stakes internally).
    event DepositZap(
        address indexed caller,
        address indexed receiver,
        uint256 diemIn,
        uint256 sdiemReceived,
        uint256 shares
    );

    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event AdminTransferStarted(address indexed currentAdmin, address indexed pendingAdmin);
    event AdminTransferred(address indexed oldAdmin, address indexed newAdmin);
    event TokenRecovered(address indexed token, address indexed to, uint256 amount);
    event SwapRouterUpdated(address indexed oldRouter, address indexed newRouter);
    event MaxSlippageUpdated(uint256 oldBps, uint256 newBps);
    event OraclePoolUpdated(address indexed oldPool, address indexed newPool);
    event TwapWindowUpdated(uint32 oldWindow, uint32 newWindow);
    event TickSpacingUpdated(int24 oldSpacing, int24 newSpacing);
    event MinDiemPerUsdcUpdated(uint256 oldMin, uint256 newMin);
    event MinHarvestUpdated(uint256 oldMin, uint256 newMin);

    // ── Views ───────────────────────────────────────────────────────────────

    function sdiem() external view returns (IsDIEMv2);
    function diem() external view returns (IERC20);
    function usdc() external view returns (IERC20);
    function admin() external view returns (address);
    function pendingAdmin() external view returns (address);
    function paused() external view returns (bool);

    /// @notice Unclaimed USDC rewards accrued in sDIEM v2, available for harvest.
    function pendingHarvest() external view returns (uint256);

    // ── Harvest config ──────────────────────────────────────────────────────

    function swapRouter() external view returns (address);
    function oraclePool() external view returns (address);
    function twapWindow() external view returns (uint32);
    function tickSpacing() external view returns (int24);
    function maxSlippageBps() external view returns (uint256);
    function minDiemPerUsdc() external view returns (uint256);
    function minHarvest() external view returns (uint256);

    // ── Harvest (permissionless) ────────────────────────────────────────────

    /**
     * @notice Claim USDC from sDIEM v2, swap to DIEM, stake into sDIEM v2.
     * @param deadline Unix timestamp by which the underlying swap must execute.
     *        Caller-supplied at submission time (Pashov #1).
     */
    function harvest(uint256 deadline) external;

    // ── Zap deposit ─────────────────────────────────────────────────────────

    /**
     * @notice Deposit raw DIEM. Vault stakes it into sDIEM v2 internally
     *         and mints csDIEM v2 shares against the resulting sDIEM.
     * @param diemAmount Amount of DIEM to deposit (18 decimals).
     * @param receiver Recipient of the minted csDIEM v2 shares.
     * @return shares csDIEM v2 shares minted.
     */
    function depositDIEM(uint256 diemAmount, address receiver) external returns (uint256 shares);

    // ── Admin ───────────────────────────────────────────────────────────────

    function pause() external;
    function unpause() external;
    function transferAdmin(address newAdmin) external;
    function acceptAdmin() external;
    function setSwapRouter(address newRouter) external;
    function setMaxSlippage(uint256 newSlippage) external;
    function setOraclePool(address newPool) external;
